const staticData = $getWorkflowStaticData('global');

const items = $input.all();

if (!items.length) {
    return [];
}

const data = items[0].json;
const payload = data.body ?? data;

const currentText = payload.message ?? '';

if (!currentText) {
    throw new Error('pageText не знайдено');
}

// Перевіряємо, чи змінився Inbox
if (staticData.lastInboxText === currentText) {
    console.log('Inbox не змінився. Повідомлення не надсилаємо.');
    return [];
}

// Зберігаємо новий стан
staticData.lastInboxText = currentText;

console.log('Inbox змінився. Надсилаємо сповіщення.');

return items;

const items = $input.all();

return items.map(item => {
    const data = item.json.body ?? item.json;
    const text = data.pageText ?? '';

    // Відокремлюємо історію повідомлень
    const messagesStart = text.indexOf('Messages');

    if (messagesStart === -1) {
        return {
            json: {
                message: 'Повідомлення не знайдено'
            }
        };
    }

    const messagesText = text.slice(messagesStart);

    // Видаляємо системні елементи інтерфейсу
    const lines = messagesText
        .split('\n')
        .map(line => line.trim())
        .filter(Boolean)
        .filter(line =>
            !['Messages', 'Send'].includes(line) &&
            !line.includes('message deleted')
        );

    return {
        json: {
            message: lines.slice(0, 3).join('\n')
        }
    };
});
